SELECT d.dept_name, CASE WHEN d.budget >= 3069000 THEN 'high' WHEN d.budget >= 1984000 THEN 'mid' ELSE 'low' END AS budget_bucket, ROUND((100 * SUM(CASE WHEN e.level = 'L3' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_l3 FROM employees e INNER JOIN departments d ON e.dept_id = d.id WHERE e.hire_date >= '2023-07-21' GROUP BY d.dept_name, CASE WHEN d.budget >= 3069000 THEN 'high' WHEN d.budget >= 1984000 THEN 'mid' ELSE 'low' END HAVING ROUND((100 * SUM(CASE WHEN e.level = 'L3' THEN 1 ELSE 0 END)) / COUNT(*), 1) > 43
